solution:
function climbStairs(n) {
  if (n <= 2) return n;                    // 1 step: 1 way; 2 steps: 2 ways
  let twoBelow = 1;                        // ways(1)
  let oneBelow = 2;                        // ways(2)
  for (let step = 3; step <= n; step++) {
    const current = oneBelow + twoBelow;   // last move was a 1-step or a 2-step
    twoBelow = oneBelow;
    oneBelow = current;
  }
  return oneBelow;
}

