// Safety check first: time n = 35. Plain recursion makes ~30 million calls here (tens of ms);
// memoization or a table finishes in well under a millisecond. Only if it's fast do we try n = 70,
// so an exponential solution fails with a message instead of freezing the page.
const t0 = performance.now();
const r35 = climbStairs(35);
const ms = performance.now() - t0;
assertEqual(r35, 14930352);
assert(ms < 15, 'climbStairs(35) took ' + ms.toFixed(1) + ' ms. That looks exponential: add memoization (or build a table) so each n is computed once.');
assertEqual(climbStairs(70), 308061521170129);
